// Выдвижной текст

const btn = document.querySelector(".tgl_btn");
if (btn) {
  const btnTxt = btn.querySelector(".txt");
  const hiddenTxt = document.querySelector(".togle_txt__hidden");
  hiddenTxt.style.display = "none";

  btn.addEventListener("click", () => {
    if (hiddenTxt.style.display == "block") {
      hiddenTxt.style.display = "none";
      btnTxt.innerHTML = "Раскрыть текст";
      btn.classList.remove("active");
    } else {
      hiddenTxt.style.display = "block";
      btnTxt.innerHTML = "Закрыть текст";
      btn.classList.add("active");
    }
  });
}

const btnsFile = document.querySelectorAll("[data-file]");
btnsFile.forEach((btnFile) => {
  const btn = btnFile.querySelector(".file-up");
  const btnName = btn.querySelector(":scope span");
  const btnInp = btnFile.querySelector("input[type=file]");

  btn.addEventListener("click", () => {
    btnInp.click();
  });

  btnInp.addEventListener("change", () => {
    btnName.innerHTML = btnInp.files[0].name;
  });
});

